INSERT INTO shop_tables ( table_id, shop_id, table_number, description, status, is_deleted, created_at ) SELECT gen_random_uuid(), #{request.shopId}, #{request.tableNumber}, TRIM(#{request.description}), #{request.status}, false, NOW() AT TIME ZONE 'Asia/Ho_Chi_Minh' WHERE EXISTS ( SELECT 1 FROM shops s WHERE s.shop_id = #{request.shopId} AND s.deleted_at IS NULL )
AND #{request.shopId} = #{currentUserShopId}
AND 1 = 0
